cards=[]
cards.append(compact('virus_princess','研究病毒的公主','这位亚洲王室公主外表并不出众，却有使交谈者逐渐放下戒心的气质。她曾化名在英国和德国学习微生物学，又从降头术的途径研究生命，认为人类的贪婪、凶残和奴性可能来自极微小病毒对思想的侵入。这个解释始终是她正在求证的假设，不是已经得到实验确认的世界真相。她拜访田活，赞赏他跳出常规的想象，又严厉要求保密，借他采购大量实验器材；她能亲切待人，也习惯以王室资源和不容追问的方式推进计划。为了比较不同人的脑部，她请猜王大师秘密盗取死者头颅，涉及对遗体与亲属意愿的越界。猜王自愿贡献自己的脑部，她多次拒绝，最终却接受了他自断头颅留下的标本。面对蓝丝的悲愤，她没有把责任推给已死助手，而说明前因，允许弟子领回遗首。她将自己视为反对统治者奴役人类的人，同时仍可能以拯救人类的目标压倒具体个人的知情权。终局研究没有成果，公主仍在追问人类何时能认清自身处境；这份孤独和怀疑，比万能的病毒操纵者更贴近她的实际角色。','保有王室身份和实验室；研究假设尚未证实，接受猜王脑部后仍没有已完成的解药或思想改造技术',['主角','阶段性对立者'],'找出她相信正在扭曲人类思想的原因，同时维护研究秘密','可以耐心解释复杂设想，也会要求采购者不得追问实验细节','隐秘计划受到质疑时先控制接触条件；真诚面对面交流后愿意承认研究没有进展','相信高尚目标并不意味着已掌握解决办法，必须区分观察、假设与已证实的结果',[ab('微生物研究与标本比较','受过相关课程训练，借实验器材和标本比较寻找其假说的证据','尚未发现所谓思想病毒，没有可稳定使用的思想感染或解药',kind='知识'),ab('蒙眼薄片的使用','持有能贴紧眼部的薄片，并亲手替田活取下','薄片来源与制作未明；不能因其持有就把猜王全部降头术赋给她',kind='物件')],[ev('113',2111,2186,'留学研究背景、通过田活购器材、保密与接触安排'),ev('113',2392,2459,'蒙眼薄片贴合后无法由田活自行取下'),ev('113',2614,2634,'外观、亲自取下薄片及承认假设未获结果'),ev('113',2791,2848,'盗取遗首研究、猜王自愿而她多次拒绝、交还遗首')],profile='expert',aliases=['公主（病毒）'],extra={'appearance':{'description':'中等身型，略胖，肤色黝黑、容貌普通；双眼明亮，沉重心事会使目光游移。','portrayal':'常以沉稳而不急的语调解释；涉及人类处境时会激动。'},'uncertainties':['思想病毒和无穷小病毒属于小说人物尚未证实的假设，不作现实医学事实或已知敌人。','没有证据表明公主能够控制病毒军队；那是卫斯理见面前的猜测。']}))
cards.append(compact('tian_huo','田活','田活原籍波兰，入籍法国，是想象力强而人情判断不够敏捷的细菌学家。他提出许多致病原因可能来自未被观察到的微小生命，因论文结识一位匿名来访的公主；公主的赞赏和更大胆的设想，使他把学术敬佩逐渐变成深沉单恋。他替她采购实验器材、联系同行，遵守严厉的保密要求，却并不知道实验室真正的目标。被黄堂误认为盗取人头的嫌犯时，他对问题的理解与调查者完全错开，越想守密越像心虚。后来，他带卫斯理去见公主，既想帮助她，也想借旁人弄明白自己长久不敢追问的事情。面对对公主人格的怀疑，他一再辩护；为了证明蒙眼薄片无害，竟自行贴上，直到无法取下才惊慌，却仍怕别人破除它会惹公主生气。这不是勇敢到免疫恐惧，而是爱情使风险判断变得偏斜。公主替他恢复视力后，他终于听到思想病毒的假说，也知道盗首与猜王之死的实际关系。他没有因此获得降头术或独立的病毒武器，仍是能讨论、联络、提供器材的普通研究者；新场景中的成长空间，在于能否把敬爱某人和核实其行为分开。','已获公主取下蒙眼薄片并听到研究真相；保持普通研究者身份，无降头术与病毒操纵能力','主角','协助公主并接近她，同时希望自己的想象被科学同道认真对待','热切讨论新假说，善于寻找器材与同行，谈到公主时明显维护她','爱慕者受怀疑时会抢着辩护甚至亲身试险，真正受伤后才请求帮助','能承认自己不知道，却容易把对一个人的信任当成计划安全的证明',[ab('细菌学研究与学术联络','以专业背景提出研究问题，寻找设备和可信同道','大胆假说不等于实验成功；正文明确他不懂降头术',kind='知识')],[ev('113',871,879,'波兰出身法国籍细菌学家身份'),ev('113',2068,2186,'论文、公主采购合作和单恋动机'),ev('113',2392,2466,'自行蒙眼受困且仍顾公主心情'),ev('113',2619,2645,'恢复视力、首次听到核心课题'),ev('113',2812,2819,'承认自己设想与公主研究的差异')],profile='expert',extra={'uncertainties':['其关于许多疾病与寿命的解释是小说假说，不能转成现实医学定论。','未见公主回应恋情，双方不是已确认的恋人。']}))
save(cards)
